<?php
require_once __DIR__ . '/includes/bootstrap.php';
require_once __DIR__ . '/includes/admin.php';
require_once __DIR__ . '/includes/staff.php';
require_admin();
ensure_admin_schema();
ensure_staff_tables();
$timeLogs = db()->query("SELECT t.clock_in AT TIME ZONE 'Asia/Manila' AS clock_in_local, t.clock_out AT TIME ZONE 'Asia/Manila' AS clock_out_local, COALESCE(t.total_seconds, FLOOR(EXTRACT(EPOCH FROM (t.clock_out - t.clock_in)))::INT) AS total_seconds, s.first_name, s.last_name, s.position FROM staff_time_log t JOIN user_account u ON u.user_id = t.user_id LEFT JOIN staff s ON s.user_id = u.user_id ORDER BY t.clock_in DESC LIMIT 100")->fetchAll();
$philippineTimeZone = new DateTimeZone(APP_TIMEZONE);
$auditLogs = db()->query("SELECT a.action, a.affected_table, a.affected_record_id, a.details, a.action_timestamp, COALESCE(s.first_name || ' ' || s.last_name, u.username) AS actor FROM audit_log a JOIN user_account u ON u.user_id = a.user_id LEFT JOIN staff s ON s.user_id = u.user_id ORDER BY a.action_timestamp DESC LIMIT 150")->fetchAll();
$pageTitle = 'Audit and time logs';
require __DIR__ . '/includes/header.php';
?>
<main class="dashboard-page staff-page"><aside class="dashboard-sidebar"><a class="dashboard-brand" href="staff_dashboard.php"><img src="assets/images/logo.png" alt="Barangay Inosluban logo"><span><strong>BARANGAY INOSLUBAN</strong><small>LIPA CITY, BATANGAS</small><small>Admin Portal</small></span></a><?php require __DIR__ . '/includes/staff_nav.php'; ?></aside><section class="dashboard-content"><div class="staff-main"><div class="staff-hero compact"><div><p class="eyebrow">SECURITY &amp; ACCOUNTABILITY</p><h1>Audit &amp; Time Logs</h1><p>Review staff attendance and every recorded processing action.</p></div></div><section class="staff-panel p-3 mb-3"><h2 class="h5">Staff time sheets</h2><div class="table-responsive"><table class="staff-table"><thead><tr><th>Staff</th><th>Position</th><th>Clock in (Philippine Time)</th><th>Clock out (Philippine Time)</th><th>Total worked</th></tr></thead><tbody><?php foreach ($timeLogs as $log): ?><?php $totalSeconds = $log['total_seconds'] === null ? null : max(0, (int) $log['total_seconds']); ?><tr><td><?= e(trim(($log['first_name'] ?? '') . ' ' . ($log['last_name'] ?? ''))) ?></td><td><?= e($log['position'] ?? '') ?></td><td><?= e((new DateTimeImmutable((string) $log['clock_in_local'], $philippineTimeZone))->format('M j, Y g:i:s A')) ?></td><td><?= $log['clock_out_local'] !== null ? e((new DateTimeImmutable((string) $log['clock_out_local'], $philippineTimeZone))->format('M j, Y g:i:s A')) : 'Active' ?></td><td><?= $totalSeconds === null ? 'In progress' : e(sprintf('%02d:%02d:%02d', intdiv($totalSeconds, 3600), intdiv($totalSeconds % 3600, 60), $totalSeconds % 60)) ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="staff-panel p-3"><h2 class="h5">Processing audit trail</h2><div class="table-responsive"><table class="staff-table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody><?php foreach ($auditLogs as $log): ?><tr><td><?= e((new DateTime($log['action_timestamp']))->format('M j, Y g:i A')) ?></td><td><?= e($log['actor']) ?></td><td><?= e($log['action']) ?></td><td><?= e($log['affected_table'] . ' #' . $log['affected_record_id']) ?></td><td><?= e((string) json_encode($log['details'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section></div></section></main>
<?php require __DIR__ . '/includes/footer.php'; ?>
